@startuml

class House {
  + address : string
  + buildingMaterial : BuildingMaterial
}

enum BuildingMaterial {
  WOOD
  BRICK
  CONCRETE
}

class Basement {
  + name : string
  + size : int
}

class EarthBasement extends Basement {
  + humidityLevel : float
}

class ConcreteBasement extends Basement {}

class SemiDetachedHouse extends House {
  + hasOwnGarden : boolean
  + numberOfWindows : int
}

class Carport {
  + isDoubleCarport : boolean
  + hasFlatRoof : boolean
}

class Garage {
  + hasAutomaticGarageDoor : boolean
}

class Company {
  + name : string
  + address : string
}

class JobLog {
  + hours : float
  + agreedPrice : float
}

House "0..1" o-- "0..1" Basement
House "1" -- "*" Company : serviced by
Company "1" -- "*" JobLog : performs
House "1" -- "*" JobLog : has
JobLog "*" -- "1" Company : performed by

SemiDetachedHouse "1" -- "2" Carport : has
SemiDetachedHouse "1" -- "1" Garage : has

@enduml

